/usr/bin/zsh -lc "python3 -c 'from pathlib import Path; import re; files=[Path(\"handbook.md\"),*Path(\"handbook\").glob(\"*.md\")]; bad=[]; links=[]
for f in files:
 s=f.read_text()
 for target in re.findall(r\"\\[["'^]]+'"\\]\\((["'^)]+)'"\\)\",s):
  p=(f.parent/target).resolve(); links.append((f,target)); bad.extend([(f,target)] if not p.is_file() else [])
print(f\"checked {len(links)} markdown links across {len(files)} pages; broken: {bad}\")'"

